/*
 * The browser libraries web-framework bundles are the versions it declares (CA-402).
 *
 * htmx and Alpine's CSP build ship as committed files under `bin/static/scripts/lib/`, copied from `node_modules` by
 * `bin/build/post-install.js` on every install. The publish job packs what is committed, with no install. So when
 * `fbf55ce` raised the ranges to htmx ^2.0.11 and Alpine ^3.17.4 without an install to regenerate the files, every
 * release from 1.39.0 to 1.46.0 shipped htmx 2.0.10 and Alpine 3.17.3, and nothing noticed: CI's own install rewrites
 * the files before any test runs. Both are now pinned exactly, so the version installed, bundled and declared is one
 * version. These tests catch a pin moved without regenerating the files locally; CI's diff check after its install
 * catches it there.
 */

const { describe, it } = require( "node:test" );
const assert = require( "node:assert/strict" );
const fs = require( "node:fs" );
const path = require( "node:path" );

const PACKAGE_ROOT = path.resolve( __dirname, ".." );
const LIB = path.join( PACKAGE_ROOT, "bin", "static", "scripts", "lib" );
const manifest = JSON.parse( fs.readFileSync( path.join( PACKAGE_ROOT, "package.json" ), "utf8" ) );

// Each bundled file, the package it comes from, and the file inside that package the postinstall copies.
const LIBRARIES = [
    { file: "htmx.min.js", dependency: "htmx.org", dist: "htmx.org/dist/htmx.min.js" },
    { file: "alpinejs-csp.min.js", dependency: "@alpinejs/csp", dist: "@alpinejs/csp/dist/cdn.min.js" }
];

describe( "the bundled browser libraries", () => {

    for ( const library of LIBRARIES ) {

        it( `pins ${ library.dependency } exactly, so one version is installed, bundled and declared`, () => {
            // A range lets an install pick a newer patch than the committed copy, and the publish job ships the copy.
            assert.match( manifest.dependencies[ library.dependency ] || "", /^\d+\.\d+\.\d+$/ );
        } );

        it( `bundles the pinned ${ library.dependency } in ${ library.file }`, () => {
            // Both libraries state their own version in the minified build, as `version:"x.y.z"`.
            const bundled = fs.readFileSync( path.join( LIB, library.file ), "utf8" );
            const stated = /version:"(\d+\.\d+\.\d+)"/.exec( bundled );
            assert.ok( stated, `${ library.file } states no version` );
            assert.equal( stated[ 1 ], manifest.dependencies[ library.dependency ] );
        } );

        it( `copies ${ library.file } byte for byte from the installed package`, () => {
            // The postinstall's source paths: a copy from anywhere else would carry the right version string and the
            // wrong file.
            const installed = require.resolve( library.dist );
            assert.ok( fs.readFileSync( path.join( LIB, library.file ) ).equals( fs.readFileSync( installed ) ) );
        } );

    }

    it( "is regenerated by the postinstall from those same paths", () => {
        const script = fs.readFileSync( path.join( PACKAGE_ROOT, "bin", "build", "post-install.js" ), "utf8" );
        for ( const library of LIBRARIES ) {
            assert.ok( script.includes( `require.resolve( "${ library.dist }" )` ), `post-install.js no longer copies ${ library.dist }` );
            assert.ok( script.includes( `"${ library.file }"` ), `post-install.js no longer writes ${ library.file }` );
        }
        assert.equal( manifest.scripts.postinstall, "node ./bin/build/post-install.js" );
    } );

} );
